/// <summary>
/// Utility class to register inventory transactions.
/// </summary>
public class METInventTransferUtility
{
}

Method.Source:
/// <summary>
/// Update inventTrans location basing on transfer order.
/// </summary>
/// <param name = "_inventTrans">Invent Trans</param>
/// <returns>Record of InventTrans</returns>
public static InventTrans updateInventTransWMSLocationByInventTransferLine(InventTrans _inventTrans)
{
    InventTransferLine inventTransferLine = InventTransOriginTransferReceive::inventTransferLine(_inventTrans.inventTransOrigin);

    if (inventTransferLine)
    {
        InventDim inventDimUpdate = _inventTrans.inventDim();
        inventDimUpdate.wMSLocationId = inventTransferLine.inventDim().wMSLocationId;
        _inventTrans.inventDimId = InventDim::findOrCreate(inventDimUpdate).inventDimId;
    }

    return _inventTrans;
}
